use std::fs

fn find(names: Vec<string>, name: string) -> int {
    let mut idx: int = -1
    for (i, n) in names.enumerate() {
        if n == name {
            idx = i
        }
    }
    idx
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = []
    let mut bals: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "open" {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if find(names, parts[1]) >= 0 {
                println("error: duplicate account")
            } else {
                names.push(parts[1])
                bals.push(amt)
                println("ok")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            let i = find(names, parts[1])
            if amt <= 0 {
                println("error: invalid amount")
            } else if i < 0 {
                println("error: unknown account ${parts[1]}")
            } else if cmd == "deposit" {
                bals[i] = bals[i] + amt
                println("ok")
            } else if bals[i] < amt {
                println("error: insufficient funds")
            } else {
                bals[i] = bals[i] - amt
                println("ok")
            }
        } else if cmd == "transfer" {
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            let a = find(names, parts[1])
            let b = find(names, parts[2])
            if amt <= 0 {
                println("error: invalid amount")
            } else if a < 0 {
                println("error: unknown account ${parts[1]}")
            } else if b < 0 {
                println("error: unknown account ${parts[2]}")
            } else if a == b {
                println("error: same account")
            } else if bals[a] < amt {
                println("error: insufficient funds")
            } else {
                bals[a] = bals[a] - amt
                bals[b] = bals[b] + amt
                println("ok")
            }
        } else if cmd == "balance" {
            let i = find(names, parts[1])
            if i < 0 {
                println("error: unknown account ${parts[1]}")
            } else {
                println("${bals[i]}")
            }
        }
    }
    let mut order: Vec<string> = names
    order.sort()
    for n in order {
        let i = find(names, n)
        println("${n} ${bals[i]}")
    }
}

